package com.bank.lifecycle.model;

import jakarta.persistence.*;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "customers")
public class Customer {

    @Id
    @Column(name = "customer_id")
    private String customerId;

    @Column(name = "full_name", nullable = false)
    private String fullName;

    // cascade ALL = PERSIST + MERGE + REMOVE + DETACH + REFRESH
    // orphanRemoval = delete a child when it LEAVES this collection (different trigger from REMOVE)
    @OneToMany(mappedBy = "customer", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Order> orders = new ArrayList<>();

    protected Customer() {}

    public Customer(String customerId, String fullName) {
        this.customerId = customerId;
        this.fullName = fullName;
    }

    public void addOrder(Order order) { orders.add(order); order.setCustomer(this); }
    public void removeOrder(Order order) { orders.remove(order); order.setCustomer(null); }

    public String getCustomerId() { return customerId; }
    public String getFullName() { return fullName; }
    public List<Order> getOrders() { return orders; }
}
