    public static CustomerView from(Customer c) {
        return new CustomerView(c.getCustomerId(), c.getFullName(),
            c.getOrders().stream()
                .map(o -> new OrderLine(o.getOrderId(), o.getDescription(), o.getAmount(), o.getStatus()))
                .toList());
    }
}
