package com.bank.lifecycle.service;

import com.bank.lifecycle.dto.CustomerView;
import com.bank.lifecycle.model.Customer;
import com.bank.lifecycle.model.Order;
import com.bank.lifecycle.repository.CustomerRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
@Slf4j
public class CustomerService {

    private final CustomerRepository customerRepo;

    // PERSIST cascade: saving a new customer inserts its new orders too
    @Transactional
    public CustomerView createWithOrders(String customerId, String name) {
        Customer customer = new Customer(customerId, name);
        customer.addOrder(new Order("ORD-" + "A", "NBI Bluechip units", new BigDecimal("100000")));
        customer.addOrder(new Order("ORD-" + "B", "NBI Liquid units", new BigDecimal("50000")));
        customerRepo.save(customer);   // CascadeType.PERSIST → INSERT customer + 2 orders
        log.info("[PERSIST cascade] saved {} and its new orders in one call", customerId);
        return CustomerView.from(customer);
    }

    // MERGE cascade: reattaching a detached customer graph updates its orders
    @Transactional
    public CustomerView mergeGraph(Customer detached) {
        Customer managed = customerRepo.save(detached); // save() → merge for existing id
        log.info("[MERGE cascade] merged {} and its detached orders", managed.getCustomerId());
        return CustomerView.from(managed);
    }

    // orphanRemoval: cancelling ONE order deletes it, customer stays
    @Transactional
    public CustomerView cancelOrder(String customerId, String orderId) {
        Customer customer = customerRepo.findWithOrders(customerId).orElseThrow();
        customer.getOrders().stream()
            .filter(o -> o.getOrderId().equals(orderId))
            .findFirst()
            .ifPresent(customer::removeOrder);  // leaves collection → orphanRemoval DELETE
        customerRepo.save(customer);
        log.info("[orphanRemoval] cancelled order {} — DELETEd, customer {} remains", orderId, customerId);
        return CustomerView.from(customer);
    }

    // REMOVE cascade: closing the account deletes the customer AND all orders
    @Transactional
    public void closeAccount(String customerId) {
        Customer customer = customerRepo.findWithOrders(customerId).orElseThrow();
        customerRepo.delete(customer);   // CascadeType.REMOVE → DELETE orders, then customer
        log.info("[REMOVE cascade] closed {} — deleted customer and all its orders", customerId);
    }

    @Transactional(readOnly = true)
    public CustomerView view(String customerId) {
        return CustomerView.from(customerRepo.findWithOrders(customerId).orElseThrow());
    }
}
```

