package com.bank.lifecycle.controller;

import com.bank.lifecycle.dto.CustomerView;
import com.bank.lifecycle.service.CustomerService;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/customers")
@RequiredArgsConstructor
public class CustomerController {

    private final CustomerService service;

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public CustomerView create(@RequestParam String customerId, @RequestParam String name) {
        return service.createWithOrders(customerId, name);
    }

    @DeleteMapping("/{customerId}/orders/{orderId}")
    public CustomerView cancel(@PathVariable String customerId, @PathVariable String orderId) {
        return service.cancelOrder(customerId, orderId);
    }

    @DeleteMapping("/{customerId}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void close(@PathVariable String customerId) {
        service.closeAccount(customerId);
    }

    @GetMapping("/{customerId}")
    public CustomerView view(@PathVariable String customerId) {
        return service.view(customerId);
    }
}
