// ─── File: src/test/java/com/bank/lifecycle/model/CascadeConfigTest.java ───
package com.bank.lifecycle.model;

import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import java.util.List;
import jakarta.persistence.CascadeType;
import jakarta.persistence.OneToMany;
import static org.assertj.core.api.Assertions.*;

class CascadeConfigTest {

    @Test
    void customerCascadesAllToOrders() throws Exception {
        Field orders = Customer.class.getDeclaredField("orders");
        OneToMany o2m = orders.getAnnotation(OneToMany.class);
        assertThat(List.of(o2m.cascade())).contains(CascadeType.ALL);
    }

    @Test
    void customerHasOrphanRemoval() throws Exception {
        Field orders = Customer.class.getDeclaredField("orders");
        OneToMany o2m = orders.getAnnotation(OneToMany.class);
        assertThat(o2m.orphanRemoval()).isTrue();
    }

    @Test
    void removeAndOrphanRemovalFireOnDifferentTriggers() {
        // CascadeType.REMOVE  → fires when the PARENT is deleted (delete(customer))
        // orphanRemoval=true  → fires when a CHILD leaves the collection (customer stays)
        // They are complementary, not the same.
        assertThat("parent-deleted").isNotEqualTo("child-removed-from-collection");
    }

    @Test
    void addOrderSetsOwningSide() {
        Customer c = new Customer("CUST-RAJESH", "Rajesh Kumar");
        Order o = new Order("ORD-100", "NBI Bluechip units", new java.math.BigDecimal("100000"));
        c.addOrder(o);
        assertThat(c.getOrders()).containsExactly(o);
    }
}
